import builtins, struct, time, numpy as np, nuka
def frames(n):
    for _ in range(n):
        app.update(True)
def run_for(seconds):
    t = time.monotonic()
    while time.monotonic() - t < seconds:
        app.update(True)
def tick():
    return app.actions.run('timeline.status')['tick']
def until_tick(n):
    deadline = time.monotonic() + 60.0
    while tick() < n:
        assert time.monotonic() < deadline, tick()
        app.update(True)
def step(n):
    t = tick()
    app.actions.run('sim.step', steps=n)
    until_tick(t + n)
    frames(3)
def targets():
    return np.asarray(app.world.download_field(nuka.Field.DRIVE_TARGET), dtype=np.float32).reshape(app.world.env_count, -1)[0].copy()
def fails(action, text, **args):
    from nuka.editor.app import ActionError
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def nkml(path, obs, act, seed):
    rng = np.random.default_rng(seed)
    dims = [obs, 32, act]
    with open(path, 'wb') as f:
        f.write(struct.pack('<IIIff', 0x4E4B4D4C, 1, obs, 5.0, 1.0))
        f.write(np.zeros(obs, np.float32).tobytes() + np.ones(obs, np.float32).tobytes())
        f.write(struct.pack('<I', 2))
        for l in range(2):
            f.write(struct.pack('<III', dims[l], dims[l + 1], 1 - l))
            f.write((rng.standard_normal((dims[l + 1], dims[l])) / np.sqrt(dims[l])).astype(np.float32).tobytes())
            f.write((0.3 * rng.standard_normal(dims[l + 1])).astype(np.float32).tobytes())
nkml('${out}/rand.bin', 235, 12, 1)
nkml('${out}/obs100.bin', 100, 12, 2)
nkml('${out}/act6.bin', 235, 6, 3)
with open('${out}/junk.bin', 'wb') as f:
    f.write(b'nope')
builtins.pl_frames, builtins.pl_run_for, builtins.pl_tick, builtins.pl_until_tick = frames, run_for, tick, until_tick
builtins.pl_step, builtins.pl_targets, builtins.pl_fails = step, targets, fails
